//"Nueva clase" (No lo es, es una extensión, adelante)
public class ModuloTierra extends Modulo {
//Atributos, protected por si acaso
    protected int capacidad;
    protected int energiaDescarga;
    protected String estacion;
    protected int totalDescargado;

//Constructor default
    public ModuloTierra() {
        //El super para traer datos
		super();
        capacidad = 0;
        energiaDescarga = 0;
        estacion = "";
        totalDescargado = 0;
    }

//Constructor con datos
    public ModuloTierra(String id, String nombre, int salud, boolean activo, int clase, float costo, int capacidad, int energiaDescarga, String estacion,int totalDescargado) {
		//Traigo lo que neccesito
        super(id, nombre, salud, activo, clase, costo);
		//Agrego lo nuevo
        this.capacidad = capacidad;
        this.energiaDescarga = energiaDescarga;
        this.estacion = estacion;
        this.totalDescargado = totalDescargado;
    }

//Setters y Getters, yay
    public void setCapacidad(int newCapacidad) {
        capacidad = newCapacidad;
    }

    public int getCapacidad() {
        return capacidad;
    }


    public void setEnergiaDescarga(int newEnergiaDescarga) {
        energiaDescarga = newEnergiaDescarga;
    }

    public int getEnergiaDescarga() {
        return energiaDescarga;
    }


    public void setEstacion(String newEstacion) {
        estacion = newEstacion;
    }

    public String getEstacion() {
        return estacion;
    }


    public void setTotalDescargado(int newTotalDescargado) {
        totalDescargado = newTotalDescargado;
    }

    public int getTotalDescargado() {
        return totalDescargado;
    }


    @Override
	//El proceso es diferente para la clase, aunque la logica es la misma
    public void procesoCiclo(Mision mision) {
		//Solo está activa
        if (!activo) {
            System.out.println(nombre + " no operó porque está inactivo.");

		//Solo se hay energía
        } else if (mision.getEnergiaDisponible() < energiaDescarga) {
            System.out.println(nombre + " no operó por energía insuficiente.");

		//Si no hay nada que hacer
        } else if (mision.getDatosOrbita() <= 0) {
            System.out.println(nombre + " no operó porque no hay datos en órbita.");

		//Si todo esto funciona
        } else {
			//declaro una "descarga", etnero, me sirve para calculos y datos al final
            int descarga;
            if (mision.getDatosOrbita() >= capacidad) {
                descarga = capacidad;
            } else {
                descarga = mision.getDatosOrbita();
            }


            // Consume toda la energía de una descarga (sin importarle si agarró todo o si se llenó, solo lo gasta de fijo)
            mision.setEnergiaDisponible(
                mision.getEnergiaDisponible() - energiaDescarga
            );


            // Quita los datos descargados de la órbita (los que pueda.)
            mision.setDatosOrbita(mision.getDatosOrbita() - descarga);


            // Los agrega al total histórico de la misión
            mision.setDatosDescarga(mision.getDatosDescarga() + descarga);


            // Los agrega al histórico de este módulo
            totalDescargado += descarga;

			//Mensaje de descarga
            System.out.println(nombre + " descargó " + descarga + " MB.");
        }
    }


    @Override
	//Características exclusivas
    public void mostrarCaracteristicas() {
        System.out.println("Estación: " + estacion);
        System.out.println("Capacidad de descarga: " + capacidad + " MB");
        System.out.println("Energía por descarga: " + energiaDescarga);
        System.out.println("Total histórico descargado: "+ totalDescargado + " MB");
    }
}